const chokidar = require('chokidar');

let timer;
const debounce = (fn, ms) => (...args) => {
  clearTimeout(timer);
  timer = setTimeout(() => fn(...args), ms);
};

const handler = debounce((path) => {
  console.log(`changed: ${path}`);
}, {{debounce_ms}});

